import React from 'react';

export default function About() {
  return (
    <div className="max-w-5xl mx-auto py-20 px-6">
      <h1 className="text-5xl font-black tracking-tight mb-4 text-center">Who we are</h1>
      <p className="text-gray-600 text-lg max-w-2xl mx-auto text-center mb-12">Founded with a passion for making city travel accessible, we have grown into a trusted rental service across the region.</p>
      <div className="bg-white p-10 border rounded-lg shadow-sm">
        <h2 className="text-2xl font-bold mb-2">Our Corporate Mission</h2>
        <p className="text-gray-600 leading-relaxed">To optimize local asset deployment pipelines, guaranteeing clear transactional access protocols to safely maintained transport assets across industrial and consumer requirements.</p>
      </div>
    </div>
  );
}
